import { test, expect } from '@playwright/test';

test.describe('Reorder list items by drag and drop', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should drag and drop an item to a new position', async ({ page }) => {
    const firstItem = page.getByRole('listitem', { name: 'Item 1' });
    const secondItem = page.getByRole('listitem', { name: 'Item 2' });

    await firstItem.dragTo(secondItem);

    const reorderedFirstItem = await page.getByRole('listitem', { name: 'Item 2' }).evaluate(el => el.previousElementSibling);
    expect(reorderedFirstItem).toHaveText('Item 1');
  });

  test('should maintain the order after reordering', async ({ page }) => {
    const listItems = await page.locator('ul').locator('li').allTextContents();
    expect(listItems).toEqual(['Item 1', 'Item 2', 'Item 3']); // Adjust based on expected order after drag and drop
  });
});
